// Дэд дугаар (эзэн 10-27 «дэд дугаарууд бас ашиглах»): 1. → 1.1 → 4.1.1. Дугаарыг CSS counters() тавина
// (src/css/custom.css «.sb-num») — Docusaurus 2.3 хуудасны sidebar_label-ийг label-ээс давуу үздэг тул
// нэрт дугаар бичиж болохгүй. Энд зөвхөн «N. » угтварыг авч, дугаарлах мөрөнд sb-num класс тавина.
function mark(items) {
  return items.map((it) => {
    if (typeof it === "string") return { type: "doc", id: it, className: "sb-num" };
    if (it.type === "category") return { ...it, className: "sb-num", items: mark(it.items) };
    return it; // autogenerated — дугаарлахгүй
  });
}

for (const name of Object.keys(sidebars)) {
  sidebars[name] = sidebars[name].map((it) => {
    if (it.type !== "category" || !/^\d+\. /.test(it.label)) return it;
    return { ...it, label: it.label.replace(/^\d+\. /, ""), className: "sb-num", items: mark(it.items) };
  });
}

module.exports = sidebars;
